import pathlib,csv,json
p=pathlib.Path(__file__).resolve().parent;rows=[]
def add(page,front,endpoint,back,source,fields,refresh='À l’ouverture / actualisation explicite',empty='Non disponible si champ absent ; zéro uniquement si explicitement retourné',error='Erreur de chargement ; aucune valeur inventée',confidence='Élevée — contrat et code tracés'):
 for field in fields.split(','):
  field=field.strip();rows.append(dict(PAGE=page,UI_ELEMENT=field,DISPLAYED_VALUE='Valeur API ou transformation documentée ; voir captures served après correction',FRONTEND_FIELD=front+('.'+field if field else ''),API_ENDPOINT=endpoint,BACKEND_FIELD=back+('.'+field if field else ''),ULTIMATE_SOURCE=source,REFRESH_MECHANISM=refresh,EMPTY_STATE=empty,ERROR_STATE=error,CONFIDENCE=confidence))
